"New stripes suit you!":"نئے پھول تم پر جچتے ہیں!",
"Pod inbound! Reinforcements!":"کیپسول آ رہا ہے! کمک!",
"Anyone remember why the sky is a portal?":"کسی کو یاد ہے آسمان پورٹل کیوں ہے؟",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"کہتے ہیں شافٹ میں کودو تو دشمن کے ہاں نکلتے ہو۔ میں آزمانے سے رہا۔",
"The Swarm painted their visors red again. Show-offs.":"جھنڈ نے پھر وائزر سرخ رنگ دیے۔ شوخے۔",
"Ore, ore… when do we get some oil?":"دھات، دھات… تیل کب ملے گا؟",
"I dreamt I was a toaster. It was peaceful.":"خواب میں میں ٹوسٹر تھا۔ بڑا سکون تھا۔",
"Quiet. Too quiet.":"خاموشی ہے۔ حد سے زیادہ خاموشی۔",
"See that? Our base is above the Swarm base again. Portals, man.":"دیکھا؟ ہمارا اڈا پھر جھنڈ کے اڈے کے اوپر ہے۔ پورٹل، یار۔",
"Diman, if you're reading this — we need a vacation.":"دیمان، اگر یہ پڑھ رہے ہو — ہمیں چھٹی چاہیے۔",
