"Battle loaded: {0}":"میچ لوڈ ہو گیا: {0}",
"Autosaved":"خودکار محفوظ ہو گیا",
"robot war · the sky is a portal":"روبوٹ جنگ · آسمان پورٹل ہے",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"شہابیے پر خوش آمدید! آپ کنسورشیم کے جنگی روبوٹ ہیں۔ ماؤس سے آس پاس دیکھو اور WASD سے چلو۔",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"ہوائی بیگ: Shift ٹیپ کرو — چھلانگ، Shift دبائے رکھو — پرواز۔ توانائی زمین پر بحال ہوتی ہے۔",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"فائر — ماؤس کا بایاں بٹن۔ نشانہ — ماؤس کا دایاں بٹن: زیادہ درست اور زوم کے ساتھ۔ چند فائر کرو۔",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"ری لوڈ — R۔ گولیاں درمیانی فاصلے پر، 20–50 میٹر میں سب سے زور سے لگتی ہیں۔",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"راکٹ — Q۔ ٹینکوں اور عمارتوں کے خلاف۔ ایک راکٹ داغو۔",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"اوپر اے آئی حکمت کار کا حکم ہے۔ سبز تیروں کے ساتھ دوڑو: راستے پر آپ کی رفتار تیز ہوتی ہے۔ نقطے پر قبضہ — بیکن کے پاس کھڑے رہو۔",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"آپ کا دستہ تمہیں کور دیتا ہے: بائیں طرف ان کی تصویریں اور صحت ہے۔ پیچھے رہ جائیں تو وہ رکنے کو کہیں گے۔",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"‏{0} — لڑائی چھوڑے بغیر فوری یونٹ بدلو: لڑائی کے سب سے قریبی دستے یا ٹینک میں کود جاؤ۔ آزماؤ۔",
"Next to a tank or turret press E to take control. Or just carry on.":"ٹینک یا برج توپ کے پاس E دبا کر اسے کنٹرول کرو۔ یا بس آگے بڑھتے رہو۔",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"اب حکمتِ عملی۔ اوپر دائیں \"◩ حکمتِ عملی\" پر ٹیپ کرو — میدانِ جنگ کا اوپری منظر۔",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"اب حکمتِ عملی۔ {0} دباؤ (یا اوپر بائیں \"◩ حکمتِ عملی\") — میدانِ جنگ کا اوپری منظر۔",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"حکمتِ عملی میں کیوریٹر تمہاری مدد کرتا ہے: اوپر والی ونڈو بتاتی ہے کیا کرنا ہے، فریم بٹن دکھاتا ہے، دائرہ نقشے پر جگہ بتاتا ہے۔ اس کے تین مشورے پورے کرو۔",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"کوئی دستہ منتخب کرو اور سبز \"▶ کنٹرول\" بٹن پر ٹیپ کرو — اسی سپاہی کے طور پر دوبارہ لڑائی میں۔ جب تم لڑتے ہو تو اے آئی حکمت کار فوج خود چلاتا ہے۔",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"کوئی دستہ منتخب کرو اور {0} دباؤ یا سبز \"▶ کنٹرول\" دباؤ — اسی سپاہی کے طور پر دوبارہ لڑائی میں (کچھ منتخب نہ ہو تو — اپنے سپاہی میں)۔ جب تم لڑتے ہو تو اے آئی حکمت کار فوج خود چلاتا ہے۔",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"تربیت مکمل! غول نے حملہ شروع کر دیا ہے۔ ہمت سے، سپاہی!",
