"New in v6":"‏v6 میں نیا",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"نشانچی جیسی فائرنگ: فوری گولیاں، 720 راؤنڈ فی منٹ والی رائفل، مشین گن، جھٹکا، ماؤس کے دائیں بٹن سے نشانہ، میگزین اور R سے ری لوڈ، ہٹ کے نشان",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"بھاری کششِ ثقل، تیز ردِعمل والا جیٹ پیک، Z سے جھپٹا یا ہوا میں 2× جیٹ؛ دوسری یونٹ پر کنٹرول لینے پر ہتھیار اب ساتھ نہیں اڑتا",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"انجینئر: انجینئر چنو، عمارت چنو، نقشہ رکھو؛ دھات کی رگوں پر ایکسٹریکٹر؛ «دھات» پر کلک کرو — آمدنی کہاں سے آتی ہے اور کیسے بڑھائیں",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"سرمئی بٹن دبائے جا سکتے ہیں — وجہ اور حل کا بٹن دکھائیں گے؛ بڑے بٹن، «جاری کام» پٹی، «▶ کنٹرول»، Tab — ایک ہی کلید",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"جھٹکوں اور پلٹنے کے بغیر حکمت عملی کیمرا، کرسر کی طرف زوم، منی میپ کو کھینچا جا سکتا ہے",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"نئی گاڑیاں: چھاپہ مار \"Jackal\"، \"Grad\" MLRS (ہدف کا پیچھا کرنے والے راکٹ)، \"Hammer\" مارٹر؛ نحل (Swarm) کے پاس \"Wasp\"، \"Hive\"، \"Trebuchet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"اسٹریٹیجسٹ احکامات نہیں بدلتا اور آواز سے تنگ نہیں کرتا؛ لڑائیاں تمہارے قریب ہوں گی؛ B — منتقلی، Shift+B — لڑائی کے بیچ؛ قطب نما، H — کون سا ہدف",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"آزادانہ کھیل (K) اور اکیلے کارروائی (J)، F2 — پری سیٹس؛ Esc — وقفہ اور واپسی؛ محفوظ کردہ: سلاٹس، فائل کی برآمد اور درآمد",
"New in v5.3":"‏v5.3 میں نیا",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"پرواز: شہابیہ سے دور کشش زیادہ، ہوا میں C — بریک، دھکا تیزی سے موڑتا ہے؛ اب پورٹل میں «اٹکنا» نہیں",
"New in v5":"‏v5 میں نیا",
"Endless war by default and battle scale: normal, large, epic":"بے انتہا جنگ بطور ڈیفالٹ اور لڑائیوں کا پیمانہ: عام، بڑا، عظیم الشان",
"Save and load the battle (autosave every 3 minutes)":"لڑائی کو محفوظ اور لوڈ کرنا (اور ہر 3 منٹ بعد خودکار محفوظ)",
"Squadmates with callsigns: portraits, health and live chatter":"کال سائن والا دستہ: تصویریں، صحت اور زندہ گفتگو",
"Fog of war in strategy, friends and foes outlined differently":"حکمت عملی میں جنگ کی دھند، اپنے اور دشمن مختلف انداز میں نمایاں",
"Camera fly-over when switching, portal aurora instead of rings":"بدلتے وقت کیمرے کی پرواز، حلقوں کی جگہ پورٹل کی روشنی",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"ذیلی کام، آسمان کے ذریعے شارٹ کٹ، پہلی مہم کے ماڈیول سامان کے ساتھ، بلور، گڑھوں میں برف، گرد کے طوفان",
"Training, cinema mode with video recording, escort vehicles from the strategist":"تربیت، ویڈیو ریکارڈنگ کے ساتھ سینما موڈ، اسٹریٹیجسٹ کی طرف سے محافظ گاڑیاں",
