"The Swarm is counter-attacking {0}! Get ready to defend.":"سوارم {0} پر جوابی حملہ کر رہا ہے! دفاع کے لیے تیار ہو جاؤ۔",
"You're going solo. {0} returns to the strategist. {1} — call them back.":"تم اکیلے کارروائی کر رہے ہو۔ {0} اے آئی اسٹریٹجسٹ کے حکم میں جا رہا ہے۔ {1} — واپس بلاؤ۔",
