"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"کنسورشیم کا بھاری بندوقچی اب ہڈیوں والا اصلی 3D ماڈل ہے: کھڑا ہوتا ہے، چلتا ہے، ہتھیار لیے دوڑتا ہے، چلتے چلتے فائر کرتا ہے اور تباہ ہونے پر گرتا ہے",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"ماڈل شہابیے کی سطح کے عمود پر کھڑا ہوتا ہے، نشانے کے مطابق دھڑ موڑتا ہے اور مشین گن تھامے رکھتا ہے؛ دور سے اینیمیشن کم بار اپڈیٹ ہوتی ہے تاکہ FPS نہ گرے",
