"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"جیٹ پیک اور ہوائی جہاز بعد میں کھلتے ہیں — طیارہ شکن اور برج توپیں لگانے کا وقت ہے۔ تب تک بیرک اور میکھ فیکٹری بنائیں۔",
