"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"دستہ آپ کے پیچھے چل رہا ہے۔ ☰ کھولیں ← «وقفہ» ← «دستہ میرے ساتھ» ٹائل — وہ «اکیلا کارروائی» بن جائے گا۔",
