"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"آپ حرکت کرنا، اڑنا، فائر کرنا، آڑ لینا اور دستے کو کمان دینا سیکھ چکے ہیں۔ آگے — اصلی میچ۔",
