"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"محفوظ تجربہ گاہ: دشمن ابھی بھی ساکن پتلے ہیں، کوئی آپ پر گولی نہیں چلاتا۔ مرحلہ تب ہی شمار ہوتا ہے جب آپ خود عمل کریں۔",
"Show others (training for the other device)":"دوسرے دکھائیں (دوسرے آلے کے لیے تربیت)",
