"Back to the normal device mode":"آلے کے عام موڈ پر واپس جائیں",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"دوسرے آلے کی تربیت صفحے کو اسی کے موڈ میں دوبارہ لوڈ کرے گی (پی سی — ماؤس اور کی بورڈ، فون — ٹچ؛ پی سی پر ٹچ کو Chrome میں آزمانا آسان ہے: F12 ← فون کا آئیکن)۔",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"تربیت ×4: پی سی اور فون کے لیے الگ الگ مرحلہ وار «حکمت عملی» اور «نشانچی» اسباق۔ پتلوں کے ساتھ محفوظ سینڈ باکس، درست بٹن کی نمایاں روشنی، تیر، متحرک کیز، ماؤس اور اشارے؛ مرحلہ صرف اصل عمل پر شمار ہوتا ہے، «مرحلہ دہرائیں»، اوپر پیش رفت اور آخر میں انعام",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"‏«تربیت» مینو آپ کے آلے کے اسباق خود دکھاتا ہے؛ «دوسرے دکھائیں» — کسی بھی آلے پر چاروں؛ «پرانی تربیت (v7.1)» بدستور موجود ہے",
"New in v7.2":"‏v7.2 میں نیا",
