"More":"مزید",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"قریب دشمن کی گاڑی یا عمارت ہے — اس پر ٹیپ کریں: راکٹ جائے گا۔",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"بہت سے دشمن ہیں — دائیں طرف خالی جگہ پر دو بار ٹیپ کریں: ریفلیکس وقت کو سست کر دے گا۔",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"نشانہ دشمنوں کے جمگھٹ پر لگائیں اور 3 بار ٹیپ کریں — مداری حملہ۔",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"بایاں انگوٹھا — چلنا، دایاں — نظر۔ نشانہ دشمن پر ہو تو فائر خود ہوتا ہے۔",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"بائیں کنارے پر ⇑ — جیٹ پیک: کودنے کے لیے ٹیپ کریں، اڑنے کے لیے دبائے رکھیں۔",
"Old v7.2 layout":"‏v7.2 کی پرانی ترتیب",
"Drag a finger on the right half of the screen — a look stick appears under it.":"اسکرین کے دائیں نصف پر انگلی چلائیں — انگلی کے نیچے نظر کی اسٹک ظاہر ہوگی۔",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"بائیں طرف چھوئیں اور انگلی چلائیں — انگلی کے نیچے اسٹک ظاہر ہوگی۔ سبز نشان تک پہنچیں۔",
"Hold the \"Jet\" button at the left edge.":"بائیں کنارے پر «جیٹ» بٹن دبائے رکھیں۔",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"دائیں اسٹک سے پتلے پر نشانہ لگائیں — نشانہ ہدف پر ہو تو آپ کا سپاہی خود فائر کرتا ہے۔",
"Tap the dummy on the screen — a rocket flies.":"اسکرین پر پتلے پر ٹیپ کریں — راکٹ جائے گا۔",
"Tap the dummy — a grenade flies in an arc, right at it.":"پتلے پر ٹیپ کریں — دستی بم قوس بناتا ہوا سیدھا اسی پر جائے گا۔",
"Double tap an empty spot on the right quickly.":"دائیں طرف خالی جگہ پر جلدی سے دو بار ٹیپ کریں۔",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"کمزور فونز کے لیے ہلکا موڈ: کم ریزولوشن، سائے اور بگاڑ کے بغیر، آدھے بوٹس اور پارٹیکلز، زیادہ سے زیادہ 30 فریم/s؛ FPS < 25 ہو تو ریزولوشن خود کم کر دیتا ہے۔ فون پر بطورِ طے شدہ آن ہے (ترتیبات ← گرافکس ← «ہلکا موڈ»؛ یا لنک میں ?lite=1 / ?lite=0)۔",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"فون: نئی ترتیب۔ بائیں — چلیں، دائیں — نظر (دونوں اسٹکس انگلی کے نیچے ظاہر ہوتی ہیں)۔ صرف بایاں انگوٹھا — «آٹو»؛ دایاں بھی استعمال ہو تو سپاہی صرف تب خود فائر کرتا ہے جب نشانہ دشمن پر ہو۔ دشمن پر ٹیپ — راکٹ یا دستی بم، 2 ٹیپ — ریفلیکس، 3 ٹیپ — مداری حملہ۔ ری لوڈ خودکار۔ جیٹ پیک — بائیں کنارے کا بٹن۔ نچلے کونے خالی ہیں، منی میپ کونے میں ہے، اشارے کراس سے بند ہوتے ہیں، ہدف سمیٹا جا سکتا ہے۔ پرانی ترتیب: ترتیبات ← فون۔",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"اشارے (پاپ اپ اور رہنما) — ترتیبات میں ایک ہی سوئچ۔ آپ کون ہیں (سپاہی یا گاڑی کی قسم) — HUD میں «آپ: …» کا لیبل۔ رائفل اور مشین گن کی آپٹکس شفاف ہیں۔ «ہتھیاروں کا ذخیرہ» پینل دائیں جانب جڑا ہے، سمیٹا اور بند کیا جا سکتا ہے۔ «دستے کے بغیر اکیلے» (J) ہٹا دیا گیا۔ AI حکمت کار کی آواز اب ایک ہی جملہ بار بار نہیں دہراتی۔ ٹینکوں میں برج بمقابلہ ڈھانچے کا اشاریہ ہے۔ حکمت عملی کی تربیت کے آغاز میں کرسر اب غائب نہیں ہوتا۔",
