"Possess vehicles and drones":"گاڑیوں اور ڈرونز پر قبضہ کریں",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"توپ پر: {0}۔ اے آئی چلاتا ہے، آپ فائر کرتے ہیں۔ {1} — اتریں",
