"Strategist: troopers dropping to you — +{0} (−{1} ore)":"‏AI حکمت کار: آپ کی طرف سپاہی اتر رہے ہیں — +{0} (−{1} عفرہ)",
"Hold on, sending troopers your way":"ڈٹے رہیں، آپ کی طرف سپاہی بھیج رہا ہوں",
"· basic{0}":"‏· بنیادی{0}",
