"Advanced: custom class order":"ایڈوانسڈ: کلاسوں کی اپنی ترتیب",
"Voice of hints & curator":"اشاروں اور رہنما کی آواز",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"فون: اسٹک کے تین موڈ۔ صرف بایاں — «آٹو» (مضبوط مقناطیس، مگر گولیاں کمزور)۔ صرف دایاں — نشانہ خود آن ہو جاتا ہے، مقناطیس مضبوط، فائر زیادہ درست۔ دونوں ایک ساتھ — نشانہ نہیں، مقناطیس اور درستی کم۔ دائیں طرف 👁 بٹن — انٹرفیس چھپائیں/واپس لائیں۔",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"فون: حکمت عملی سادہ کر دی گئی — صرف مہندس اور عمارتیں۔ بائیں طرف کارڈز (مہندس، مفرقہ، بیرک…): ٹیپ کریں — کیمرا وہاں جاتا ہے، نیچے فوراً دکھائی دیتا ہے کیا بنانا/تیار کرنا ہے۔ «جنگ میں» — اوپر بائیں۔ فوج خود لڑتی ہے۔ مکمل حکمت عملی — ترتیبات ← فون۔",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"قبضہ — دو خانے: «دستے» اور «گاڑیاں» (فون پر گاڑیاں بطورِ طے شدہ بند ہیں — انہیں اے آئی چلاتا ہے)۔ گاڑیاں بند ہوں تو اپنی گاڑی کے پاس E (فون پر — دائیں طرف کا بٹن) دبا کر اس کی توپ سنبھالیں: گاڑی خود چلتی ہے، آپ فائر کرتے ہیں۔ کلاسوں کی پرانی اپنی ترتیب «ایڈوانسڈ» میں ہے۔ قبضے پر یونٹ ریڈیو پر جواب دیتا ہے۔",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"سمارٹ اشارے: بنیادی اشارے دوسرے آغاز کے بعد خود بجھ جاتے ہیں، مگر جو فیچر آپ نے کبھی استعمال نہیں کیا گیم اس کی نشاندہی کرے گی۔ خانے: بنیادی / ایڈوانسڈ / نایاب، اور الگ سے — اشاروں اور رہنما کی آواز۔",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"ریفلیکس ہلاکتوں سے چارج ہوتا ہے (سلسلہ — زیادہ)۔ ساتھی پیچھے رہ جائیں یا مارے جائیں — حکمت کار آپ کے پاس نئے اتارتا ہے (عام کمک سے مہنگے)۔ v7.2gfx کا گرافکس اور آواز شامل کر دیے گئے: دھماکوں کے بادل، دھواں، ملبہ، شافٹ اور گڑھوں کی صوتیات۔ بلڈ کی تاریخ اب اصلی ہے۔",
