"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"آسمان ایک پورٹل ہے: اوپر اڑیں تو شہابیہ کی دوسری طرف نکلیں گے۔",
"Follow the strategist's orders — XP for them is doubled and tripled.":"اسٹریٹجسٹ کے احکام پر عمل کریں — ان کا تجربہ دگنا اور تگنا ہو جاتا ہے۔",
