"Bullets hit hardest at medium range, 20–50 meters.":"گولیاں درمیانی فاصلے، 20–50 میٹر پر سب سے زیادہ مار کرتی ہیں۔",
"To win, destroy the Swarm HQ and all its key buildings.":"جیتنے کے لیے Swarm کا HQ اور اس کی تمام اہم عمارتیں تباہ کریں۔",
