"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"سنیما موڈ — اسپلٹ اسکرین: بائیں اسٹریٹجسٹ بوٹ (اڈے اور فوج کا اوپر سے منظر)، دائیں شوٹر بوٹ پہلے شخص کے منظر میں۔ نیچے بٹن (اور کیز S، P): «اسپلٹ اسکرین» اور «★ سب تعمیر» — فوٹیج کے لیے دونوں اڈے تعمیر اور اپ گریڈ۔",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"کرہ اور شہابیہ کے آر پار سرنگیں اب نہیں رہیں — شہابیہ ٹھوس ہے، لڑائی صرف سطح پر ہوتی ہے۔",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"فون: 👁 انٹرفیس چھپاتا ہے مگر جیٹ پیک، ⇆، اسٹکس اور مشن کا نشان رہنے دیتا ہے۔ «◎ نشانہ» (صرف دایاں انگوٹھا) — نمایاں طور پر زیادہ مضبوط اور وسیع مقناطیس؛ تینوں موڈز کے مقناطیس کی طاقت — ترتیبات ← کنٹرولز ← «ایڈوانسڈ»۔ گاڑی کی گن پر بٹن کا نام «اتریں» ہوتا ہے۔",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"تربیت: فون پر صرف فون کی تربیتیں، پی سی پر صرف پی سی کی۔ سبھی 4 «🛠 ڈیولپر» مینو میں ہیں۔ ڈیولپر موڈ اور اسلحہ خانہ اب ایک ہی مینو ہیں (لڑائی میں — اوپر دائیں «🛠 مینو»، پی سی پر F8 بھی)۔",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"گرافکس اسٹائل «Dendy (8-بٹ)» اور «16-بٹ»: ترتیبات ← گرافکس ← «گرافکس اسٹائل» (تفصیل — ⚙ بٹن)۔ اگر میچ کے ابتدائی ~10 s میں FPS 24 سے کم ہو تو Dendy خود چالو ہو جاتا ہے (20 سے بھی کم ہو تو — اور بڑا پکسل، 120 لائنیں)؛ اوپر کی پٹی «معمول پر لوٹیں» ہمیشہ کے لیے عام گرافکس بحال کر دیتی ہے۔ مینو میں آپ کا اپنا انتخاب ہمیشہ مقدم رہتا ہے۔",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"‏3D ماحول کے ماڈل (کھنڈر، تباہ شدہ سامان، مورچے) — صرف وہ جنہیں اچھی ریٹنگ ملی، ضرورت پر انٹرنیٹ سے لوڈ ہوتے ہیں۔ بند کرنے کے لیے: ترتیبات ← گرافکس ← «نئے 3D ماحولیاتی ماڈل»۔",
