"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"سپاہیوں سے تعمیر: E (فون پر «داخل ہوں») اپنی تعمیراتی جگہ پر — سپاہی خود بناتا ہے، قریب کے ساتھی مدد کرتے ہیں۔ اگر انجینئر مصروف ہوں تو اسٹریٹجسٹ خود مدد مانگتا ہے — «تعمیراتی جگہ» کا نشان۔",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"اسٹریٹجسٹ کے نشان: اسٹریٹجسٹ تمہارے قریب دشمن کے جمگھٹ پر ⌖ لگاتا ہے — 8 s بعد وہاں توپ خانہ حملہ کرتا ہے اور قریب کے اپنے «گراد» MLRS بوچھاڑ کرتے ہیں۔ اسٹریٹجسٹ موڈ سے تمہارا اپنا توپ خانے کا حملہ بھی «گراد» کی مدد کے ساتھ ہوتا ہے۔",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"کارگو کنٹینرز اور گرے ہوئے سیٹلائٹس میں اسلحے کے ذخیرے (📦 70 m سے نظر آتے ہیں): E — 90 s کے لیے مشین گن، آتش گیر گولیاں یا راکٹ، ساتھ بھرے ہوئے دستی بم۔ رینگنا: Ctrl — لیٹو / کھڑے ہو جاؤ (نیچا، زیادہ خاموش اور درست نشانہ، مگر آہستہ)۔",
