"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"‏«▶ ابھی کھیلیں» — مینو کا پہلا بٹن: پورٹل آسمان کے نیچے مختصر پرواز — اور سیدھا لڑائی میں (چھوڑنے کے لیے کوئی بھی کی یا ٹیپ)۔",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"گولیاں لگنے کا احساس ہوتا ہے: دھاتی آواز اور چنگاریاں، نشانے کے پاس تباہی کا نشان (سر پر — پیلا)، ×N سلسلہ، دھماکوں سے ہموار لرزش، اہم تباہیوں پر سلو موشن۔ لرزش، سلو موشن اور اشارہ ترتیبات میں بند کیے جا سکتے ہیں۔",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"میچ کا نتیجہ: وقت، تباہیاں، بہترین سلسلہ، ★ MVP اور بہترین دستہ، میچ کارڈ — «⇪ شیئر کریں»، PNG یا کھیل کا لنک۔",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"وسائل کے نیچے بائیں طرف «اب کیا کرنا ہے» کا اشارہ: حکمت کار کا حکم، قبضے کا مقام، جھنڈ کی پیش قدمی۔ ✕ یا F7 — سمیٹو۔",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"ٹیب بند یا چھوٹا کرنے پر لڑائی خود محفوظ ہو جاتی ہے — مینو میں «⟲ جاری رکھیں»۔",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"‏v7.5 «🕘 کھیل کا ورژن» مینو میں موجود ہے — اگر نیا پسند نہ آئے۔ اب گمنام اعداد و شمار (نام اور ای میل کے بغیر) بھیجے جاتے ہیں؛ بند کرنا — ترتیبات میں۔",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"‏«ابھی کھیلیں»، گولیوں کا ردعمل، شیئر کارڈ کے ساتھ میچ کا نتیجہ، «کیا کرنا ہے» کا اشارہ، آٹو سیو",
"and older: v7.5, v7.4, milestones v1–v7.0":"اور پرانے: v7.5، v7.4، سنگ میل v1–v7.0",
"New in v7.6":"‏v7.6 میں نیا",
"NEW IN v7.6":"‏v7.6 میں نیا",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"میچ سے پہلے دھڑا چنو: «کنسورشیم» (طاقتور زرہ میں بھاری پیادہ، زرہ اور توپ خانہ) یا «جھنڈ» (رفتار، ڈرونز کے جھنڈ، بگاڑ والے بھاری فائر)۔ اے آئی دوسرے کو چلاتا ہے۔ انتخاب یاد رکھا جاتا ہے۔",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"ہر دھڑے کی اپنی گاڑیاں اور منفرد چیزیں ہیں: کنسورشیم کے پاس — ٹینک «گینڈا» اور «سیرامائٹ پلیٹیں»، جھنڈ کے پاس — «ڈرونز کا جھنڈ» اور «فیز جیٹ پیک»۔ توازن بوٹس کے میچوں سے جانچا گیا ہے۔",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"دھماکوں کے گڑھے: توپ خانہ، راکٹ اور ٹینک کی توپیں شہابیہ میں گڑھے کھودتی ہیں — ان میں چل سکتے ہو، گاڑی چلا سکتے ہو اور اوٹ بھی لے سکتے ہو۔",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"سپاہی کے لیے تیسرے فرد کا منظر (V، یاد رکھا جاتا ہے؛ فون پر — کنٹرول) اور گاڑی کا ہموار کیمرا جس میں نشان بتاتا ہے کہ توپ کا گولہ کہاں گرے گا۔",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"ورژن v7.6 مینو «🕘 گیم ورژن» میں موجود ہے — اگر نیا پسند نہ آئے۔",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"کنسورشیم / سوارم دھڑے میچ سے پہلے انتخاب کے ساتھ، دھماکوں کے گڑھے، تیسرے فرد کا منظر",
"and older: v7.6, v7.5, milestones v1–v7.0":"اور پرانے: v7.6، v7.5، سنگ میل v1–v7.0",
