"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"ہیروئن (ہر طرف 1): خود دشمن کے علاقوں میں ٹیلی پورٹ ہوتی ہے اور روبوٹ کاٹ ڈالتی ہے؛ قبضہ کر کے ہاتھ سے کھیل سکتے ہو۔",
"is ready. She works on her own (AUTO) — possess her to play manually":"تیار ہے۔ خود کام کرتی ہے (آٹو) — ہاتھ سے کھیلنے کے لیے قبضہ کرو",
