"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"روبو نِنجا: تلوار والی سائبورگ۔ بیرک میں «پروٹوکول «سایہ»» کی تحقیق سے کھلتی ہے (میکھ فیکٹری درکار)۔ خود دشمن کے علاقوں میں ٹیلی پورٹ ہوتی ہے، دشمنوں کو کاٹ ڈالتی ہے (خون نہیں — چنگاریاں)، جھپٹتی ہے، شروکن پھینکتی ہے، دشمن نِنجا سے دوبدو لڑتی ہے۔ اس میں قبضہ کریں — AUTO موڈ یا دستی کنٹرول (فون پر اپنے بٹن)۔",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"ریڈیو پورٹل میٹیور: EDMITRY کے 103 ٹریک گیم کے اندر۔ کلید 5 (بدلی جا سکتی ہے)، فون پر — ☰ ← ترتیبات ← آواز۔ آواز اور \"لڑائی میں خود چلے\" ترتیبات میں؛ دھماکوں اور ریڈیو کی آواز پر موسیقی دھیمی ہو جاتی ہے۔",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"نئی زبانیں: ازبک اور تاجک — مکمل؛ چینی، ہسپانوی، پرتگالی — جزوی۔ مینو میں \"نیا میچ\" کے ساتھ زبان کا نیا انتخاب۔",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"فون: \"آئیکن چھپائیں\" 👁 باقی بٹنوں کو دائیں کنارے پر سلیقے کی قطار میں جمع کرتا ہے؛ پورٹریٹ میں اب اوورلیپ نہیں ہوتا؛ iPhone — گیم اب Safari کے اشاروں سے نہیں ٹکراتا، اور \"Share ← Add to Home Screen\" اسے پوری اسکرین پر چلاتا ہے۔",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"‏v7.8.1 سے: کونے میں ☰ مینو (وقفہ، دوبارہ، تربیت، گرافکس)، خودکار Dendy نہیں، فون پر ✋ ایکشن بٹن۔ v7.8.1 اور v7.8 \"🕘 گیم ورژن\" مینو میں موجود ہیں۔",
