"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"آپ کے یونٹ کبھی کبھی مدد مانگتے ہیں: ریڈیو پر آواز، \"درخواست\" کارڈ اور ✋ نشان۔ دستہ دب گیا ہے — اس کے قریب دشمنوں کو ختم کریں۔ انعام: بیس سے کیپسول میں سپاہی، بگی کے پچھلے حصے سے بندوق، بندوقچی کی نشست یا مداری کور۔ نہیں چاہیے — ✕ یا بس نظرانداز کریں۔",
