"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"محاذ رک گیا — ہیڈکوارٹر پیش رفت پیش کرتا ہے۔ Y — قبول۔ ریلے کو 8 s قریب دشمن کے بغیر تھامیں: دشمن کا نقشہ 60 s نظر آئے گا۔ جنریٹر — دشمن کی برج توپیں 2 منٹ خاموش۔ اسٹریٹجسٹ موڈ میں — \"دستے کو سونپیں\"۔ دشمن بھی ایسا کر سکتا ہے: ⚠ پر نظر رکھیں۔",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"آپ کے یونٹ مدد مانگتے ہیں: \"درخواست\" کارڈ اور ✋ نشان۔ دبے ہوئے دستے کے قریب دشمنوں کو ختم کریں — انعام پائیں۔ ✕ — چھوڑ دیں۔",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"ہیرو \"الو\" مہم پیش کرتا ہے — \"قبول کریں\" ٹیپ کریں۔ ★ تک جائیں، پہرے داروں کو ختم کریں، پائلٹ کے پاس ٹھہریں۔",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"محاذ رک گیا — \"قبول کریں\" ٹیپ کریں اور ریلے کو 8 s تھامیں: دشمن کا نقشہ ایک منٹ کھلے گا۔",
