"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"کمزور جگہ — پیٹ کے نیچے چمکتا مرکزہ: نیچے سے نقصان ×{0}۔ بگاڑ کی شعاع اور علاقائی دھمک؛ رکاوٹیں پھلانگتا ہے — فاصلہ رکھو، ٹولی میں مت کھڑے ہو۔",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"مقابلہ: فضائی بم اور توپ خانہ (×{0})، راکٹ (×{1})، قالینی بمباری؛ گولیاں بمشکل خراش ڈالتی ہیں (×{2})۔",
